	for _, cb := range launchCheckboxes() {
		t.Run(cb.name, func(t *testing.T) {
			f := newKeysForm()
			focusLaunchField(f, cb.field(f))
			start := cb.get(f)

			f, _ = f.Update(testutil.Key("space"))
			if cb.get(f) == start {
				t.Errorf("space on %s left it at %v, want it flipped", cb.name, start)
