func TestPasteReachesTheFocusedTextField(t *testing.T) {
	tests := []struct {
		name, label, paste, want string
	}{
		{"URL", "URL", "https://git.example.com", "https://git.example.com"},
		{"with a space", "IDE command", "code -n", "code -n"},
