			m.input.SetValue("")
			tab, field := m.activeTab, m.focusedField

			m = feed(t, m, testutil.Paste(tc.paste))

			if got := m.input.Value(); got != tc.want {
				t.Errorf("%s field = %q after pasting %q, want %q", tc.label, got, tc.paste, tc.want)
